  if (event.kind === "tool_receipt") {
    const detail = event.detail && typeof event.detail === "object" ? event.detail as Row : {};
    const tools: Record<string, string> = { file_read: "已读取文件", file_write: "编辑了文件", file_revise: "编辑了文件", shell_inspect: "运行了命令", python_compile: "运行了命令", git_status: "运行了命令", numeric_ast: "运行了命令", browser_get: "已搜索网页" };
