      <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>{event.quest_id && <button className="text-button" aria-label="查看关联任务" onClick={() => onQuest(event.quest_id!)}>查看关联任务{relatedQuest ? ` · ${relatedQuest.title}` : ""}</button>}<dl>{Object.entries(detail).filter(([key]) => !(typeof detail.command === "string" && ["stdout", "output", "stderr"].includes(key))).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数", status: "状态", risk: "风险" } as Record<string, string>)[key] || key}</dt><dd>{key === "tool" ? toolLabel(value) : key === "status" ? statusLabel(value) : key === "risk" ? riskLabel(value) : text(value)}</dd></div>)}</dl><small>记录 ID：{event.event_id}</small>
    </div></AnimatedDetails>;
}

function EventGroup({ item, quests, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; quests: Quest[]; onQuest: (id: string) => void; onInspect: () => void }) {
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  return <AnimatedDetails className="event-group" onInspect={onInspect} summaryLabel={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined} summary={<><ActivityIcon /><span className="event-label">{summary}</span><Chevron /></>}>
    <div className="event-detail">{item.events.map((event) => <EventLine key={`${event.kind}:${event.event_id}`} event={event} quests={quests} onQuest={onQuest} onInspect={onInspect} />)}</div>
  </AnimatedDetails>;
}
function groupEvents(items: TimelineItem[]): DisplayItem[] {
  const grouped: DisplayItem[] = [];
  for (const item of items) {
    if (item.type !== "event") { grouped.push(item); continue; }
    const last = grouped[grouped.length - 1], questId = item.value.quest_id || null;
    if (last?.type === "group" && last.questId === questId) last.events.push(item.value);
    else grouped.push({ type: "group", questId, events: [item.value] });
  }
  return grouped;
}

export default function ChatTimeline({ messages, events, outgoing, quests, approvals, native,
  connected, historyMore, historyBusy, timelineError, conversationError, approvalError,
  canRetry, scrollRef, onScroll, onInspect, onLoadOlder, onRetry, onQuest, onApproval, approvalsBlocked, onApprovalDecision }: {
  messages: ChatMessage[]; events: TimelineEvent[]; outgoing: Outgoing[]; quests: Quest[]; approvals: Row[];
  native: boolean; connected: boolean; historyMore: boolean; historyBusy: boolean; timelineError: string;
  conversationError: string; approvalError: string; canRetry: boolean; scrollRef: RefObject<HTMLDivElement>;
  onScroll: () => void; onInspect: () => void; onLoadOlder: () => void; onRetry: (item: Outgoing) => void;
  onQuest: (id: string) => void; onApproval: (id: string) => void;
  approvalsBlocked: boolean; onApprovalDecision: (item: Row, decision: "APPROVED" | "REJECTED") => void;
}) {
  const items = groupEvents(mergeTimeline(messages, events, outgoing));
  const active = quests.filter((quest) => !isClosedQuest(quest.status)).sort((left, right) => Number(needsQuestAttention(right.status)) - Number(needsQuestAttention(left.status)));
  return <div className="timeline" ref={scrollRef} onScroll={onScroll} onMouseUp={() => { if (window.getSelection()?.toString()) onInspect(); }} aria-label="对话历史">
    {historyMore && <button className="text-button history" disabled={historyBusy} onClick={onLoadOlder}>{historyBusy ? "正在加载…" : "加载更早的消息与记录"}</button>}
    {conversationError && <p className="notice error" role="alert">{conversationError}</p>}
    {timelineError && <p className="notice error" role="alert">过程记录暂不可用：{timelineError}</p>}
    {!items.length && <div className="empty-conversation"><svg className="empty-symbol" width="56" height="56" viewBox="0 0 56 56" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><rect x="20" y="5" width="16" height="12" rx="3" /><path d="M28 17v9m-15 8v-8h30v8" /><rect x="5" y="34" width="16" height="12" rx="3" /><rect x="35" y="34" width="16" height="12" rx="3" /></svg><h2>告诉 FORGE 你要完成什么</h2><p>描述目标、约束和验收要求，后台任务会把进展带回这里。</p></div>}
    {items.map((item) => {
      if (item.type === "group") return <EventGroup key={`${item.events[0].kind}:${item.events[0].event_id}`} item={item} quests={quests} onQuest={onQuest} onInspect={onInspect} />;
      if (item.type === "outgoing") return <article key={`outgoing:${item.value.requestId}`} className="message from-user"><div className="message-meta"><span className="message-avatar">你</span><strong>你</strong><span>{item.value.status === "sending" ? "发送中" : "发送失败"}</span></div><div className="message-body"><MarkdownMessage content={item.value.content} native={native} onInspect={onInspect} />{item.value.status === "failed" && <div className="outgoing-error" role="alert">{item.value.error || "请求未完成"} · 请求 ID：<code>{item.value.requestId}</code><button className="text-button" disabled={!canRetry} onClick={() => onRetry(item.value)}>使用原请求重试</button></div>}</div></article>;
      const message = item.value, meta = messageMetadata(message.metadata);
      return <article key={message.id} className={`message ${message.role === "user" ? "from-user" : "from-agent"}`}><div className="message-meta"><span className="message-avatar">{message.role === "user" ? "你" : "F"}</span><strong>{message.role === "user" ? "你" : "FORGE"}</strong>{meta.execution_mode === "mock" && <span>模拟</span>}{meta.execution_mode === "live" && <span>真实执行</span>}{message.role !== "user" && meta.execution_mode !== "live" && meta.execution_mode !== "mock" && <span>来源未知</span>}<time>{message.created_at ? new Date(message.created_at).toLocaleString() : ""}</time></div><div className="message-body"><MarkdownMessage content={message.content} native={native} onInspect={onInspect} /></div>{message.role !== "user" && <CopyReply content={message.content} onInspect={onInspect} />}</article>;
    })}
    {connected && (active.length > 0 || approvals.length > 0) && <section className="timeline-updates" aria-label="任务与审批更新">
      <div className="timeline-updates-label">已加载的任务与审批</div>
      {approvals.slice(0, 3).map((item) => {
        const quest = quests.find((candidate) => candidate.id === item.quest_id);
        return <div className="timeline-update approval-card" key={text(item.id)}>
          <button className="approval-summary" aria-label={`需要审批 · ${text(item.action_type)} 风险 ${text(item.risk)} · ${text(item.resource_scope)}`} onClick={() => onApproval(text(item.quest_id, ""))}>
            <span><strong>{quest?.title || "关联任务暂未加载"}</strong><small>{statusLabel(item.status, "待审批")} · {toolLabel(item.action_type)} · {riskLabel(item.risk)}</small></span><span aria-hidden="true">›</span>
          </button>
          <div className="approval-scope"><span>{text(item.resource_scope)}</span><small>计划版本 {text(item.plan_revision)}</small></div>
          <AnimatedDetails className="approval-details" onInspect={onInspect} summary={<><span>操作详情</span><Chevron /></>}><dl><dt>参数摘要</dt><dd className="mono break">{text(item.parameter_digest)}</dd><dt>原因</dt><dd>{text(item.reason)}</dd><dt>过期时间</dt><dd>{text(item.expires_at)}</dd></dl></AnimatedDetails>
          <div className="button-row">{(["APPROVED", "REJECTED"] as const).map((decision) => <button key={decision} className={decision === "APPROVED" ? "button primary" : "button"} disabled={approvalsBlocked || typeof item.parameter_digest !== "string" || typeof item.plan_revision !== "number"} onClick={() => onApprovalDecision(item, decision)}>{decision === "APPROVED" ? "批准" : "拒绝"}</button>)}</div>
        </div>;
      })}
      {approvals.length > 3 && <p className="notice">已加载的审批中另有 {approvals.length - 3} 项待处理，审批页按任务筛选 · <button className="text-button" onClick={() => onApproval(text(approvals[0]?.quest_id, ""))}>按任务查看审批</button></p>}
      {active.slice(0, 3).map((quest) => <button className="timeline-update" key={quest.id} aria-label={`${quest.title} 状态：${quest.status} · 版本 ${quest.version}`} onClick={() => onQuest(quest.id)}><span><strong>{quest.title}</strong><small>{statusLabel(quest.status)} · 版本 {quest.version}</small></span><span aria-hidden="true">›</span></button>)}
      {active.length > 3 && <p className="notice">已加载的任务中另有 {active.length - 3} 项未结束 · <button className="text-button" onClick={() => onQuest("")}>查看全部任务</button></p>}
    </section>}
    {connected && approvalError && <p className="notice error" role="alert">审批状态暂不可用：{approvalError}</p>}
  </div>;
}
"}}}
